// ------------------------------------------------------------- request -------
// The contract wraps the service fields in "data" (plus a "call" object the test environment
// ignores); the flat shape is accepted too, so a tool that posts its body without the wrapper
// still works.
function payload(body) {
  if (!body || typeof body !== "object") return null;
  return (body.data && typeof body.data === "object") ? body.data : body;
}

function norm(v) {
  if (v == null) return "";
  if (typeof v === "number") return String(v);
  return String(v).trim();
}

function firstFilled() {
  for (let i = 0; i < arguments.length; i++) {
    const v = norm(arguments[i]);
    if (v !== "") return v;
  }
  return "";
}

function baseId(id) {
  return String(id == null ? "" : id).replace(SESSION_SUFFIX_RE, "");
}

// ------------------------------------------------------------------ seed -----
const SEED_CUSTOMERS = (SEED && SEED.customers) || [];

function baseCustomerNo(seedCustomer) {
  return seedCustomer && seedCustomer.raw ? norm(seedCustomer.raw.customerNo) : "";
}

function findSeed(id) {
  const key = String(id == null ? "" : id);
  const base = baseId(key);
  for (let i = 0; i < SEED_CUSTOMERS.length; i++) {
    const c = SEED_CUSTOMERS[i];
    if (String(c.customer_id) === key || String(c.customer_id) === base) return c;
    if (c.case_id && (String(c.case_id) === key || String(c.case_id) === base)) return c;
    const no = baseCustomerNo(c);
    if (no !== "" && no === base) return c;
  }
  return null;
}

// Card number exactly as cards.list returned it -> the customerNo that owns it.
const CARD_OWNER = {};
(function indexCards() {
  for (let i = 0; i < SEED_CUSTOMERS.length; i++) {
    const c = SEED_CUSTOMERS[i];
    const no = baseCustomerNo(c);
    const services = (c.raw && c.raw.services) || {};
    const list = services["cards.list"];
    const cards = list && list.response && list.response.data ? (list.response.data.cards || []) : [];
    for (let j = 0; j < cards.length; j++) {
      if (cards[j] && cards[j].cardNumber) CARD_OWNER[norm(cards[j].cardNumber)] = no;
    }
  }
})();

